package br.com.luis.cursos.controller;
import br.com.luis.cursos.model.*; import br.com.luis.cursos.repository.*; import org.springframework.http.HttpStatus; import org.springframework.web.bind.annotation.*; import java.util.List;
@RestController @RequestMapping("/api/matriculas") public class MatriculaController{ private final MatriculaRepository repo; private final AlunoRepository alunos; private final CursoRepository cursos; public MatriculaController(MatriculaRepository repo,AlunoRepository alunos,CursoRepository cursos){this.repo=repo;this.alunos=alunos;this.cursos=cursos;} @GetMapping public List<Matricula> listar(){return repo.findAll();} @GetMapping("/ativas") public List<Matricula> ativas(){return repo.findByStatus(StatusMatricula.ATIVA);} @PostMapping @ResponseStatus(HttpStatus.CREATED) public Matricula criar(@RequestParam Long alunoId,@RequestParam Long cursoId){Aluno a=alunos.findById(alunoId).orElseThrow(); Curso c=cursos.findById(cursoId).orElseThrow(); if(!c.isAtivo()) throw new IllegalStateException("Curso inativo"); Matricula m=new Matricula(); m.setAluno(a); m.setCurso(c); return repo.save(m);} @PatchMapping("/{id}/status") public Matricula status(@PathVariable Long id,@RequestParam StatusMatricula valor){Matricula m=repo.findById(id).orElseThrow(); m.setStatus(valor); return repo.save(m);} }
